// ============================================================
// SAFE ZONES (Meta UI overlays per placement, HARDE regel)
// Percentages, robuust over alle output-formaten.
// ============================================================
function buildSafeZoneInstruction(placement) {
  var intro = '\n\nSAFE ZONE REQUIREMENTS (HIGHEST PRIORITY, this overrides any other framing instruction in this prompt). Meta overlays its own interface on top of this ad, so there are reserved margins that must stay clear. RULE: no text, headline, body copy, CTA button, price, badge, Trustpilot element or the WELLSHAVE wordmark may touch or enter these margins. The background scene and the product MAY bleed to the edges, but every piece of TEXT and UI must sit fully inside the central safe area with clear breathing room. Any wording such as top, bottom, bottom center, or wordmark in the corner refers to the edge of the SAFE AREA, not the physical image edge: inset it by the reserved margin. Treat the safe area as if it were the real canvas.';
  var place, margins;
  if (placement === 'stories') {
    place = 'Stories 9:16';
    margins = ' HARD RULE for this 9:16 format, non-negotiable: EVERY text and UI element (headline, body text, button or link such as "Lees verder", badge, logo, caption, category tag) must sit ENTIRELY inside the central band between 16 percent and 78 percent of the image HEIGHT, and between 8 and 92 percent of the width. The top 16 percent and the bottom 22 percent of the image are FORBIDDEN ZONES for anything textual: Meta draws its own interface there and it will cover whatever you place there. The background scene and the product may bleed to the edges, text and UI never. Compose the layout for the central band FIRST, then fill the remaining top and bottom with pure scene, texture or negative space.';
  } else if (placement === 'reels') {
    place = 'Reels 9:16';
    margins = ' HARD RULE for this 9:16 format, non-negotiable: EVERY text and UI element (headline, body text, button or link such as "Lees verder", badge, logo, caption, category tag) must sit ENTIRELY inside the central band between 16 percent and 62 percent of the image HEIGHT, and between 8 and 92 percent of the width. The top 16 percent and the ENTIRE bottom 38 percent are FORBIDDEN ZONES for anything textual: likes, comments, share and the caption cover the whole bottom third. The CTA or link sits around the vertical middle, never lower. Background and product may bleed to the edges, text and UI never. Compose for the central band FIRST, then fill top and bottom with pure scene.';
  } else if (placement === 'feed45') {
    place = 'Feed 4:5';
    margins = ' Reserved margins: top and bottom 18 percent, left and right 9 percent. Keep the wordmark, headline, body and CTA inset from every edge.';
  } else if (placement === 'wide') {
    place = 'Liggend 16:9';
    margins = ' Reserved margins: top and bottom 7 percent, left and right 5 percent. Keep the wordmark, headline, body and CTA inset from every edge, never flush to any edge.';
  } else {
    place = 'Feed 1:1';
    margins = ' Reserved margins: about 9 percent on every edge. Keep the wordmark, headline, body and CTA inset from every edge, none of them touching the top or bottom edge.';
  }
  var closer = ' Add visible empty padding between the outermost text or UI element and the nearest image edge so the layout looks intentionally designed. Concretely: IF a brand wordmark is present it sits just inside the top margin (not flush to the top edge), and IF a CTA is present it sits just inside the bottom margin (not flush to the bottom edge). A wordmark is never required; when safe-area space is tight, drop the wordmark first, the message always wins. FINAL SELF-CHECK before output: mentally draw the forbidden margins on the canvas; if ANY letter, word, button, link, badge, caption or logo crosses into them, move it inward and rebalance the whole composition. An image with text or UI inside the reserved margins is a FAILED, unusable output.';
  return intro + ' Placement is ' + place + '.' + margins + closer;
}

// Tekst-overlay enforcement: de invulvelden (headline/body/CTA) zijn de bron
// van waarheid bij generatie en overschrijven de vrije image_prompt_en tekst.
function buildTextOverlayInstruction(v) {
  if (!v) return '';
  var hl = (v.headline_nl || '').trim();
  var body = (v.body_copy_nl || '').trim();
  var cta = (v.cta_nl || '').trim();
  var out = '\n\nTEXT OVERLAY (AUTHORITATIVE, these exact texts override any different headline, body or CTA wording mentioned earlier in this prompt):';
  if (hl) out += ' Headline, must appear and be prominent, exact text: "' + hl + '".';
  if (body) out += ' Body copy, render below the headline in clean white sans-serif smaller than the headline, exact text: "' + body + '".';
  else out += ' Body copy: none, do NOT render any body text below the headline.';
  var ctaStyle = (typeof ACTIVE_BRAND !== 'undefined' && ACTIVE_BRAND === 'wellshine')
    ? 'render it as a glossy dark chocolate-brown rounded rectangular button with a polished bronze and rose-gold beveled metallic frame, a soft glossy light reflection across the top edge and subtle depth, with the label in bold WHITE text centered'
    : 'render it as a pill (dark pill with white text and a small gold arrow, or gold pill with dark text)';
  if (cta) out += ' CTA button, ' + ctaStyle + ', exact text: "' + cta + '".';
  else out += ' CTA button: none, do NOT render any CTA button or call to action.';
  out += ' Do not invent or add any other headline, body or CTA wording. The brand wordmark and any price or badge follow the description above. Keep all of this text inside the safe zone.';
  return out;
}

