let state = {
  products: [],
  library: [],
  editingProductId: null,
  pendingRefs: { product: [], lifestyle: [], usage: [], packaging: [] },
  pendingPersonaItems: { pains: [''], desires: [''], objections: [''] },
  editingPersonaId: null,
  personas: [],
  generatedImages: {}, // variation-id -> base64 data
  lastGenerated: null,
  bundleProducts: [], // array of product IDs for Bundle-Showcase mode
  pendingImport: null, // parsed products awaiting user confirmation
  generatorMode: 'scratch', // 'scratch' (vanaf nul) of 'copy' (kopieer van ad)
  sourceAd: null, // {b64, mimeType, fileName, size, uploadedAt} voor copy-mode
  pendingEditRefs: {}, // per varIndex: array van {b64, mimeType, fileName} voor edit-refs
  pendingEdits: {}, // per varIndex: array van {type, text} voor gecombineerde bewerkingen in een keer
  editMode: {}, // per varIndex: actieve bewerk-modus in het unified paneel ('adjust'|'layout'|'strip'|'add')
  basePhotos: {} // per varIndex: {b64, mimeType, fileName} voor optionele basis-foto bij eerste generatie
};

const REF_CATEGORIES = ['product', 'lifestyle', 'usage', 'packaging'];

function getRefScenePref(){ var el = document.getElementById('ref-scene-mode'); return el ? el.value : 'both'; }
function normalizeRefs(refs) {
  if (!refs) return { product: [], lifestyle: [], usage: [], packaging: [] };
  // Legacy: flat array → put everything in product bucket
  if (Array.isArray(refs)) return { product: refs.slice(), lifestyle: [], usage: [], packaging: [] };
  return {
    product: refs.product || [],
    lifestyle: refs.lifestyle || [],
    usage: refs.usage || [],
    packaging: refs.packaging || []
  };
}

function allRefs(refs) {
  const n = normalizeRefs(refs);
  return [...n.product, ...n.lifestyle, ...n.usage, ...n.packaging];
}

function refBreakdown(refs) {
  const n = normalizeRefs(refs);
  return {
    product: n.product.length,
    lifestyle: n.lifestyle.length,
    usage: n.usage.length,
    packaging: n.packaging.length,
    total: n.product.length + n.lifestyle.length + n.usage.length + n.packaging.length
  };
}

// ============================================================
// STORAGE
// ============================================================
function loadState() {
  try {
    const p = localStorage.getItem((STORAGE_PREFIX+'products_v2'));
    state.products = p ? JSON.parse(p) : [DEFAULT_PRODUCT];
    // Defensieve filter: alleen geldige product-objects behouden
    if (!Array.isArray(state.products)) state.products = [DEFAULT_PRODUCT];
    state.products = state.products.filter(p => p && typeof p === 'object' && p.id && p.name);
    if (state.products.length === 0) state.products = [DEFAULT_PRODUCT];
    // Migrate references to {product, lifestyle, packaging} structure, met null-safety
    state.products.forEach(p => {
      if (!p.category) p.category = 'Onbekend';
      p.references = normalizeRefs(p.references);
    });
    applyProductSeed();
  } catch (e) {
    console.error('loadState products fail:', e);
    state.products = [DEFAULT_PRODUCT];
  }
  try {
    const l = localStorage.getItem((STORAGE_PREFIX+'library_v2'));
    state.library = l ? JSON.parse(l) : [];
    if (!Array.isArray(state.library)) state.library = [];
  } catch (e) { state.library = []; }
  try { if (typeof loadScriptLibrary === 'function') loadScriptLibrary(); } catch (e) {}
  try {
    const pers = localStorage.getItem((STORAGE_PREFIX+'personas_v1'));
    state.personas = pers ? JSON.parse(pers) : [];
    if (!Array.isArray(state.personas)) state.personas = [];
    state.personas = state.personas.filter(per => per && typeof per === 'object' && per.id && per.name);
  } catch (e) { state.personas = []; }

  // Migratie: als v3.18 producten nog personas bevatten, verhuis ze naar state.personas met de categorie van het product
  let migrated = false;
  state.products.forEach(p => {
    if (Array.isArray(p.personas) && p.personas.length > 0) {
      p.personas.forEach(per => {
        const existing = state.personas.find(sp => sp.name === per.name && sp.category === p.category);
        if (!existing) {
          state.personas.push({
            id: per.id || ('per-' + Date.now() + '-' + Math.random().toString(36).slice(2, 6)),
            name: per.name,
            category: p.category,
            description: per.description || '',
            pains: Array.isArray(per.pains) ? per.pains : [],
            desires: Array.isArray(per.desires) ? per.desires : [],
            objections: Array.isArray(per.objections) ? per.objections : []
          });
          migrated = true;
        }
      });
      delete p.personas;
    }
  });
  if (migrated) {
    savePersonas();
    saveProducts();
  }

  // Hardcoded bodygroomer-personas, altijd aanwezig. Bestaande (bewerkte) versies met hetzelfde id worden niet overschreven.
  let seededPersona = false;
  SEED_PERSONAS.forEach(function(sp) {
    if (!state.personas.some(function(p) { return p.id === sp.id; })) {
      state.personas.push(JSON.parse(JSON.stringify(sp)));
      seededPersona = true;
    }
  });
  if (seededPersona) savePersonas();

  const aKey = localStorage.getItem('shared_anthropic_key');
  if (aKey) document.getElementById('anthropic-key').value = aKey;
  const aModel = localStorage.getItem('shared_anthropic_model');
  if (aModel) document.getElementById('anthropic-model').value = aModel;

  const oKey = localStorage.getItem('shared_openai_key');
  if (oKey) document.getElementById('openai-key').value = oKey;
  const oProxy = localStorage.getItem('shared_openai_proxy');
  if (oProxy) document.getElementById('openai-proxy').value = oProxy;
  const oModel = localStorage.getItem('shared_openai_model');
  if (oModel) document.getElementById('openai-model').value = oModel;
  const oQuality = localStorage.getItem('shared_openai_quality');
  if (oQuality) document.getElementById('openai-quality').value = oQuality;

  updateApiStatus();
}
function saveProducts() {
  try {
    // Persisteer alleen delta's: user-toegevoegde producten en bewerkte seeds.
    // Pristine seed-producten leven in de HTML-constante, niet in localStorage.
    var toStore = state.products.filter(function(p){
      if (!SEEDED_PRODUCT_IDS.includes(p.id)) return true;
      return JSON.stringify(p) !== JSON.stringify(SEEDED_BY_ID[p.id]);
    });
    localStorage.setItem((STORAGE_PREFIX+'products_v2'), JSON.stringify(toStore));
  } catch (e) {
    console.warn('products_v2 lokale opslag vol', e);
    if (!window._quotaNoted) { window._quotaNoted = true; try { toast('Lokale browseropslag zit vol, je data wordt veilig op de teamserver bewaard'); } catch(_){} }
  }
}
function applyProductSeed() {
  // Merge gehardcodete seeds in-memory met opgeslagen delta's.
  // Lees delta's RECHTSTREEKS uit localStorage, niet uit state.products,
  // zodat de DEFAULT_PRODUCT-fallback de seeds niet kan vervuilen.
  var stored = [];
  try {
    var raw = localStorage.getItem((STORAGE_PREFIX+'products_v2'));
    var parsed = raw ? JSON.parse(raw) : [];
    if (Array.isArray(parsed)) {
      stored = parsed.filter(function(p){ return p && typeof p === 'object' && p.id && p.name; });
    }
  } catch (e) { stored = []; }
  var storedById = {};
  stored.forEach(function(p){ storedById[p.id] = p; });
  var bumped = parseInt(localStorage.getItem((STORAGE_PREFIX+'seed_version')) || '0', 10) < PRODUCT_SEED_VERSION;
  var result = SEEDED_PRODUCTS.map(function(seed){
    var s = storedById[seed.id];
    if (s && !bumped) return s;              // bewaar door gebruiker bewerkte seed
    return JSON.parse(JSON.stringify(seed)); // verse seed (pristine of ververst bij bump)
  });
  stored.forEach(function(p){
    if (!SEEDED_PRODUCT_IDS.includes(p.id)) result.push(p); // user-toegevoegd
  });
  result.forEach(function(p){
    if (!p.category) p.category = 'Onbekend';
    p.references = normalizeRefs(p.references);
  });
  state.products = result;
  // Niet opslaan zolang de zware opslag (IndexedDB) nog niet geladen is EN er niks is uitgelezen:
  // anders overschrijft de pristine seed je opgeslagen wijzigingen (fotovolgorde, toegevoegde foto's).
  if (window._wgHeavyLoaded || stored.length > 0) {
    if (bumped) localStorage.setItem((STORAGE_PREFIX+'seed_version'), String(PRODUCT_SEED_VERSION));
    saveProducts();
  }
}
function saveLibrary() {
  try {
    localStorage.setItem((STORAGE_PREFIX+'library_v2'), JSON.stringify(state.library));
    return true;
  } catch (e) {
    return false;
  }
}
function loadScriptLibrary() {
  try { const r = localStorage.getItem(STORAGE_PREFIX + 'script_library_v1'); state.scriptLibrary = r ? JSON.parse(r) : []; if (!Array.isArray(state.scriptLibrary)) state.scriptLibrary = []; }
  catch (e) { state.scriptLibrary = []; }
}
function saveScriptLibrary() {
  try { localStorage.setItem((STORAGE_PREFIX + 'script_library_v1'), JSON.stringify(state.scriptLibrary || [])); return true; } catch (e) { return false; }
}
/* ===== Plan een test (v5.03): begeleide flow met Fable-spar per stap, schrijft naar creatives ===== */
var wgp = { step: 'start', mode: null, sel: {}, chats: {}, angleHist: null, winners: null, busy: false, drawerOpen: false };
var WGP_ORDER_EXPLORE = ['start','product','persona','angle','format','scene','plan'];
var WGP_ORDER_VARY = ['start','winner','varywhat','scene','plan'];
var WGP_ORDER_IDEA = ['start','braindump','plan'];
function wgpOrder(){ return wgp.mode==='vary' ? WGP_ORDER_VARY : (wgp.mode==='idea' ? WGP_ORDER_IDEA : WGP_ORDER_EXPLORE); }
var WGP_NAMEN = { start:'Start', braindump:'Idee', winner:'Winner', varywhat:'Variabele', product:'Product', persona:'Persona', angle:'Angle', format:'Format', scene:'Scene', plan:'Plan' };
var WGP_AW_MAP = { 'Unaware':'unaware', 'Problem Aware':'problem', 'Solution Aware':'solution', 'Product Aware':'product', 'Most Aware':'most' };

function wgpModel(){ var el=document.getElementById('anthropic-model'); return (el && el.value) || 'claude-fable-5'; }
function wgpEsc(t){ return escapeHtml(t==null?'':String(t)); }
function wgpSet(key,val){ if(val==null||String(val).trim()===''){ return; } wgp.sel[key]=String(val).trim(); }
function wgpLbl(key){ var v=wgp.sel[key]; if(!v) return ''; return v.length>46?v.slice(0,46)+'...':v; }

function wgpDeriveAw(){
  var a = wgp.sel.angle || '';
  if(/Curiosity|Storytelling/.test(a)) return ['Problem Aware','TOF (koud)'];
  if(/Pain|Problem/.test(a)) return ['Problem Aware','TOF (koud)'];
  if(/Comparison|Authority|Benefits/.test(a)) return ['Solution Aware','MOF (warm)'];
  if(/Social Proof|Transformation|FOMO/.test(a)) return ['Product Aware','MOF / retargeting'];
  return ['Problem Aware','TOF (koud)'];
}
function wgpAdName(){
  var clean=function(s,n){ return String(s||'').replace(/[^A-Za-z0-9]/g,'').toUpperCase().slice(0,n)||'X'; };
  var pre=(typeof ACTIVE_BRAND!=='undefined'&&ACTIVE_BRAND==='wellshine')?'WSH':'WS';
  return pre+'-'+clean(wgp.sel.product,4)+'-'+clean(wgp.sel.persona,5)+'-'+clean(wgp.sel.angle,7)+'-'+clean(wgp.sel.format,7)+'-V1';
}

/* ---------- rendering ---------- */
function wgpRender(){
  var box = document.getElementById('wgp-body');
  if(!box) return;
  var o = wgpOrder();
  // stappenbalk
  var nav = '';
  o.forEach(function(s){
    var done = wgpStepDone(s);
    var cls = (s===wgp.step)?'wgp-chip cur':(done?'wgp-chip':'wgp-chip ghost');
    nav += '<span class="'+cls+'" onclick="wgpGo(\''+s+'\')">'+WGP_NAMEN[s]+'</span>';
  });
  var crumbs='';
  [['mode','Start'],['winnerName','Winner'],['vary','Varieert'],['product','Product'],['persona','Persona'],['angle','Angle'],['format','Format'],['scene','Scene']].forEach(function(p){
    if(wgp.sel[p[0]]) crumbs += '<span class="wgp-chip sel">'+p[1]+' · '+wgpEsc(wgp.sel[p[0]].length>34?wgp.sel[p[0]].slice(0,34)+'...':wgp.sel[p[0]])+'</span>';
  });
  var h = '<div class="wgp-nav">'+nav+'</div>'+(crumbs?'<div class="wgp-nav dim">'+crumbs+'</div>':'');
  h += wgpScreen();
  box.innerHTML = h;
  var fab=document.getElementById('wgp-fab'); if(fab) fab.style.display='flex';
  var st=document.getElementById('wgp-dr-stap'); if(st) st.textContent='Stap: '+(WGP_NAMEN[wgp.step]||wgp.step);
  if(wgp.drawerOpen){ wgpRenderChat(); if(!(wgp.chats[wgp.step]&&wgp.chats[wgp.step].length)) wgpKickoff(); }
}
function wgpStepDone(s){
  var m={start:'mode',braindump:'bd',winner:'winnerName',varywhat:'vary',product:'product',persona:'persona',angle:'angle',format:'format',scene:'scene'};
  return !!wgp.sel[m[s]];
}
function wgpGo(step){ wgp.step=step; if(step==='angle') wgpLoadAngleHist(); if(step==='winner') wgpLoadWinners(); wgpRender(); }
function wgpPick(key,label,val){ wgp.sel[key]=label; if(key==='mode'){ wgp.mode=val; } wgpNext(); }
function wgpNext(){ var o=wgpOrder(); var i=o.indexOf(wgp.step); if(i===-1){ wgpGo('plan'); return; } if(i<o.length-1) wgpGo(o[i+1]); }
function wgpEigen(key,inputId){ var el=document.getElementById(inputId); var v=el?el.value.trim():''; if(!v){ toast('Typ eerst je eigen invulling, of kies een kaart',true); return; } wgp.sel[key]=v; wgpNext(); }

function wgpCard(onclick,title,sub,chip,chipCls){
  return '<button class="wgp-card" onclick="'+onclick+'"><div class="t">'+wgpEsc(title)+'</div><div class="s">'+sub+'</div>'+(chip?'<span class="wgp-tag '+(chipCls||'')+'">'+wgpEsc(chip)+'</span>':'')+'</button>';
}
function wgpFree(key,ph){
  var id='wgp-eigen-'+key;
  return '<div class="wgp-free"><textarea id="'+id+'" placeholder="'+wgpEsc(ph)+'"></textarea><button class="btn btn-small btn-ghost" onclick="wgpEigen(\''+key+'\',\''+id+'\')">Gebruik mijn eigen invulling</button></div>';
}

function wgpScreen(){
  var s = wgp.step;
  if(s==='start'){
    return '<div class="wgp-intro"><h3>Hoe begint deze test?</h3><p>Gooi je eigen ingeving erin, loop de stappen langs, of knijp een winner uit. De volgorde is een hulplijn: via de balk hierboven spring je altijd vrij heen en weer, en op elke stap kun je sparren met Fable (knop rechtsonder).</p></div>'
      + '<div class="wgp-cards c3">'
      + wgpCard("wgpPick('mode','Eigen idee','idea')",'Ik heb al een idee','Dump je ingeving in gewone taal. Fable vertaalt hem naar persona, angle, format en scene, en laat open wat nog mist.','Snelste route','gold')
      + wgpCard("wgpPick('mode','Nieuwe combinatie','explore')",'Nieuwe combinatie testen','Stap voor stap: product, persona, angle uit zijn bank, format en scene. Elke stap met ruimte voor eigen invoer.','Exploratie','')
      + wgpCard("wgpPick('mode','Variatie op winner','vary')",'Varieer op een winner','Winnende messaging vasthouden, een variabele veranderen. Kort en gericht.','Iteratie','')
      + '</div>';
  }
  if(s==='braindump'){
    return '<div class="wgp-intro"><h3>Gooi het er maar uit</h3><p>Typ zoals je denkt, half af is prima. Fable vult alleen in wat echt uit je idee volgt; de rest blijft open op het plan.</p></div>'
      + '<div class="wgp-free big"><textarea id="wgp-bd-text" placeholder="Je idee, een klantquote die bleef hangen, een TikTok die je zag..."></textarea>'
      + '<div class="wgp-row"><button class="btn btn-primary" id="wgp-bd-btn" onclick="wgpBd()">Laat Fable het plan invullen</button>'
      + '<button class="btn btn-small btn-ghost" onclick="wgp.mode=\'explore\';wgp.sel.mode=\'Nieuwe combinatie\';wgpGo(\'product\')">Liever zelf stap voor stap</button></div>'
      + '<div class="wgp-note" id="wgp-bd-status"></div></div>';
  }
  if(s==='winner'){
    var body='';
    if(wgp.winners===null) body='<div class="wgp-note">Winners laden uit de Creative Strategy-tabel...</div>';
    else if(!wgp.winners.length) body='<div class="wgp-note">Nog geen rijen met status Winner of Iterate in de tabel. Kies een andere route, of zet eerst een winnende creative in de tabel.</div>';
    else body='<div class="wgp-cards c3">'+wgp.winners.map(function(w){
      var sub=wgpEsc([w.persona,w.angle_type,w.format].filter(Boolean).join(' · '))+(w.hook_short?('<br>"'+wgpEsc(String(w.hook_short).slice(0,60))+'..."'):'');
      var chip='ROAS '+(w.roas!=null?w.roas:'?')+(w.hook_rate!=null?(' · hook '+w.hook_rate+'%'):'');
      return wgpCard("wgpPickWinner("+w.id+")",w.ad_name||('rij '+w.id),sub,chip,'gold');
    }).join('')+'</div>';
    return '<div class="wgp-intro"><h3>Welke winner knijp je uit?</h3><p>De kern (persona, angle, messaging) blijft staan; je kiest zo wat je varieert.</p></div>'+body;
  }
  if(s==='varywhat'){
    return '<div class="wgp-intro"><h3>Wat varieer je?</h3><p>E&eacute;n variabele per test. De rest blijft exact gelijk aan de winner, zo weet je straks waar het verschil vandaan kwam.</p></div>'
      + '<div class="wgp-cards c2">'
      + wgpCard("wgpPick('vary','Nieuwe hooks')",'Nieuwe hooks','Zelfde script, drie nieuwe openingen. Snelste test, meet op hook rate.','','')
      + wgpCard("wgpPick('vary','Andere opening-scene')",'Andere opening-scene','Zelfde messaging, ander probleem-beeld in de eerste 3 seconden.','','')
      + wgpCard("wgpPick('vary','Andere creator/casting')",'Andere creator','Zelfde script, ander gezicht: peer wordt expert of founder.','','')
      + wgpCard("wgpPick('vary','Ander format')",'Ander format','Zelfde angle en messaging, gegoten in een nieuw format.','','')
      + '</div>';
  }
  if(s==='product'){
    var cards=(state.products||[]).slice(0,12).map(function(p){
      return wgpCard("wgpPick('product','"+wgpEsc(p.name).replace(/'/g,"\\'")+"')",p.name,wgpEsc(p.category||'')+(p.usps&&p.usps[0]?('<br>'+wgpEsc(p.usps[0])):''),'','');
    }).join('');
    return '<div class="wgp-intro"><h3>Welk probleem lossen we op?</h3><p>Het script begint bij het probleem, niet bij het product. Kies het product en houd het probleem voor ogen dat we in beeld gaan brengen.</p></div>'
      + '<div class="wgp-cards c3">'+cards+'</div>'+wgpFree('product','Of eigen ingeving: bundel, ander product, of een probleem dat er niet tussen staat...');
  }
  if(s==='persona'){
    var cards=(state.personas||[]).slice(0,12).map(function(p){
      return wgpCard("wgpPick('persona','"+wgpEsc(p.name).replace(/'/g,"\\'")+"')",p.name,wgpEsc((p.description||'').slice(0,110)),(p.pains&&p.pains.length?p.pains.length+' pijnpunten in kaart':''),'');
    }).join('');
    return '<div class="wgp-intro"><h3>Voor wie schrijven we?</h3><p>Het script wordt gebouwd op een persona: zijn taal, zijn pijn, zijn bezwaren.</p></div>'
      + '<div class="wgp-cards c3">'+cards+'</div>'+wgpFree('persona','Of eigen ingeving: beschrijf zelf wie je wilt raken...');
  }
  if(s==='angle'){
    var hist = wgp.angleHist || {};

    /* Op resultaat gesorteerd, maar in drie groepen in plaats van één lijst.
       Eén lijst op ROAS zou de ongeteste angles ertussen strooien op een
       waarde die ze niet hebben, of ze onderaan laten verdwijnen. Dan test je
       alleen nog wat je al weet en leer je niets meer.

       bewezen  genoeg data voor een oordeel (>= 3 ads, >= EUR 300) -> op gewogen ROAS
       dun      wel geprobeerd, te weinig om iets te betekenen -> op beste losse ad
       nieuw    nog niet geprobeerd bij deze persona -> eigen volgorde van CS_ANGLES */
    /* Vrije waarden tellen mee. In de data staan angles die niet in CS_ANGLES
       voorkomen ('comparison', 'premium'); vóór deze regel werd hun historie
       wel opgehaald maar nooit getoond, dus leerde je er niets van terwijl je
       er wel geld aan uitgaf. Ze komen achter de vaste lijst, want die volgorde
       is een bewuste keuze en de rest is toeval. */
    var alle = CS_ANGLES.slice();
    Object.keys(hist).forEach(function(a){ if(alle.indexOf(a)===-1) alle.push(a); });

    var bewezen=[], dun=[], nieuw=[];
    alle.forEach(function(a){
      var st=hist[a];
      if(st && st.betrouwbaar && st.roas!=null) bewezen.push(a);
      else if(st && st.n) dun.push(a);
      else nieuw.push(a);
    });
    bewezen.sort(function(x,y){ return hist[y].roas - hist[x].roas; });
    dun.sort(function(x,y){
      var bx=hist[x].best, by=hist[y].best;
      if(bx==null && by==null) return hist[y].n - hist[x].n;   // geen cijfer: vaakst geprobeerd eerst
      if(bx==null) return 1;
      if(by==null) return -1;
      return by - bx;
    });

    var chipBewezen=function(v){
      return 'ROAS '+v.roas+' over '+v.ads+(v.ads===1?' ad':' ads')
        + (v.winnaars ? (' · '+v.winnaars+(v.winnaars===1?' winner':' winners')) : '');
    };
    var chipDun=function(v){
      return v.n+'x getest'+(v.best!=null?(' · beste ROAS '+v.best):'')+' · nog te dun voor een oordeel';
    };
    var blok=function(namen,label,chipVan,cls){
      if(!namen.length) return '';
      return '<div class="wgp-groep">'+label+'</div><div class="wgp-cards c2">'
        + namen.map(function(a){
            return wgpCard("wgpPick('angle','"+a.replace(/'/g,"\\'")+"')",a,'',chipVan(hist[a]),cls);
          }).join('')
        + '</div>';
    };

    var body = wgp.angleHist===null
      ? '<div class="wgp-note">Testhistorie laden...</div><div class="wgp-cards c2">'
        + CS_ANGLES.map(function(a){
            return wgpCard("wgpPick('angle','"+a.replace(/'/g,"\\'")+"')",a,'','','');
          }).join('') + '</div>'
      : blok(bewezen,'Werkt bij deze persona',chipBewezen,'gold')
        + blok(dun,'Geprobeerd, nog geen oordeel',chipDun,'')
        + blok(nieuw,'Nog niet geprobeerd bij deze persona',function(){ return 'Nog niet getest'; },'new');

    return '<div class="wgp-intro"><h3>De angle voor '+wgpEsc(wgp.sel.persona||'deze persona')+'</h3><p>Op volgorde van wat deze persona daadwerkelijk opleverde. Bovenaan staat alleen wat op genoeg advertenties rust; daaronder wat te dun is om iets te betekenen, en wat je nog niet geprobeerd hebt. Vraag Fable om angles in de klanttaal van deze persona.</p></div>'
      + body + wgpFree('angle','Of eigen angle, het liefst als klanttaal-citaat...');
  }
  if(s==='format'){
    var cards = CS_FORMATS.filter(function(f){return f.cat==='Video';}).map(function(f){
      return wgpCard("wgpPick('format','"+f.name.replace(/'/g,"\\'")+"')",f.name,f.cat,'','');
    }).join('');
    return '<div class="wgp-intro"><h3>Waarin gieten we het?</h3><p>Video-formats eerst; de Scriptwriter schrijft immers video. Eigen invoer kan altijd.</p></div>'
      + '<div class="wgp-cards c3">'+cards+'</div>'+wgpFree('format','Of eigen format(-mix)...');
  }
  if(s==='scene'){
    return '<div class="wgp-intro"><h3>Hoe zien we het probleem?</h3><p>De eerste seconden moeten het probleem tonen, niet benoemen. Beschrijf de scene, of spar met Fable en neem zijn voorstel over.</p></div>'
      + '<div class="wgp-free big"><textarea id="wgp-eigen-scene" placeholder="Wat zie je letterlijk in frame 1? Bv: close-up rode irritatie in de nek, hand wrijft eroverheen, badkamerlicht.">'+wgpEsc(wgp.sel.scene||'')+'</textarea>'
      + '<div class="wgp-row"><button class="btn btn-primary" onclick="wgpEigen(\'scene\',\'wgp-eigen-scene\')">Gebruik deze scene</button>'
      + '<button class="btn btn-small btn-ghost" onclick="wgpGo(\'plan\')">Overslaan, Theriot bedenkt de scene</button></div></div>';
  }
  if(s==='plan') return wgpPlanScreen();
  return '';
}

function wgpPickWinner(id){
  var w=(wgp.winners||[]).find(function(x){return x.id===id;});
  if(!w) return;
  wgp.sel.winnerName = w.ad_name || ('rij '+id);
  wgp.sel.parentId = id;
  wgpSet('product',w.product); wgpSet('persona',w.persona); wgpSet('angle',w.angle_type); wgpSet('format',w.format); wgpSet('sceneHint',w.hook_short);
  wgpNext();
}

function wgpPlanScreen(){
  var isVary = wgp.mode==='vary';
  var aw = wgpDeriveAw();
  var pickOr=function(label,key,step,sub){
    if(wgp.sel[key]) return '<div class="wgp-ovc" onclick="wgpGo(\''+step+'\')" title="Klik om te wijzigen"><div class="k">'+label+'</div><div class="v">'+wgpEsc(wgpLbl(key))+(sub?'<small>'+wgpEsc(sub)+'</small>':'')+'</div></div>';
    return '<div class="wgp-ovc pickme" onclick="wgpGo(\''+step+'\')"><div class="k">'+label+'</div><div class="v">Nog kiezen<small>klik voor deze stap, of vraag Fable</small></div></div>';
  };
  var rows='';
  if(isVary){
    rows += '<div class="wgp-ovc"><div class="k">Vertrekpunt</div><div class="v">Variatie op '+wgpEsc(wgp.sel.winnerName||'?')+'<small>parent-id '+(wgp.sel.parentId||'?')+' · kern blijft staan</small></div></div>';
    rows += pickOr('Geteste variabele','vary','varywhat','de enige knop die verschilt');
    rows += pickOr('Opening-scene','scene','scene','');
  } else {
    rows += pickOr('Product','product','product','');
    rows += pickOr('Persona','persona','persona','');
    rows += pickOr('Marketing angle','angle','angle','');
    rows += pickOr('Format','format','format','');
    rows += pickOr('Opening-scene','scene','scene','de eerste 3 seconden');
    rows += '<div class="wgp-ovc deriv"><div class="k">Afgeleid · awareness</div><div class="v">'+aw[0]+'<small>wordt meegegeven aan Theriot, pas aan in het formulier als het niet klopt</small></div></div>';
    rows += '<div class="wgp-ovc deriv"><div class="k">Afgeleid · funnel</div><div class="v">'+aw[1]+'<small>retargeting? pas aan in het formulier</small></div></div>';
  }
  var adname = isVary ? String(wgp.sel.winnerName||'WS-VAR').replace(/-V\d+$/i,'')+'-V2' : wgpAdName();
  rows += '<div class="wgp-ovc wide deriv"><div class="k">Voorgestelde ad-naam (encodeert de combinatie)</div><div class="v"><span class="wgp-adname">'+wgpEsc(adname)+'</span><small>zo koppel je Ads Manager-cijfers blind terug aan deze test</small></div></div>';
  var hypo = wgp.sel.hypo || wgpHypoVoorzet();
  return '<div class="wgp-intro"><h3>Dit gaan we bewijzen</h3><p>Pas aan wat je wilt, scherp de hypothese aan (of spar erover met Fable), en laat Theriot dan schrijven. Het plan gaat mee: bij het bewaren van het script landt alles als rij in de Creative Strategy-tabel.</p></div>'
    + '<div class="wgp-ov">'+rows+'</div>'
    + '<div class="wgp-free big"><label class="label">Hypothese</label><textarea id="wgp-hypo">'+wgpEsc(hypo)+'</textarea><div class="wgp-note">'+wgpEsc(wgpMetricNote())+'</div></div>'
    + '<div class="wgp-row"><button class="btn btn-primary btn-generate" onclick="wgpApplyAndWrite()">Schrijf script met Theriot</button>'
    + '<button class="btn btn-small btn-ghost" onclick="wgpSavePlanOnly()">Bewaar alleen het plan in de tabel</button>'
    + '<button class="btn btn-small btn-ghost" onclick="wgpReset()">Opnieuw beginnen</button></div>';
}
function wgpHypoVoorzet(){
  if(wgp.mode==='vary') return 'Als we bij '+(wgp.sel.winnerName||'de winner')+' alleen "'+(wgp.sel.vary||'een variabele').toLowerCase()+'" veranderen en de rest gelijk houden, verwacht ik betere cijfers op de primaire metric, omdat de messaging bewezen is en alleen de uitvoering verandert.';
  var aw=wgpDeriveAw();
  return 'Als we '+(wgp.sel.persona||'deze persona')+' ('+aw[0]+') targeten met de angle "'+(wgp.sel.angle||'nog te kiezen')+'" in het format '+(wgp.sel.format||'nog te kiezen')+', verwacht ik een hook rate boven 30% en hold rate boven 10%, omdat deze combinatie aansluit op het sterkste pijnpunt en nog niet eerder zo is getest.';
}
function wgpMetricNote(){
  var v=wgp.sel.vary||'';
  if(/hook/i.test(v)) return 'Primaire metric: hook rate. Hold rate en ROAS secundair.';
  if(/format/i.test(v)) return 'Primaire metric: hold rate en CTR. ROAS pas beoordelen bij voldoende conversies.';
  return 'Primaire metric: hook rate (stopt de angle de scroll?), daarna hold rate. ROAS pas beoordelen bij voldoende conversies.';
}
function wgpReset(){ wgp.step='start'; wgp.mode=null; wgp.sel={}; wgp.chats={}; wgpRender(); }

/* ---------- data ---------- */
function wgpLoadWinners(){
  if(wgp.winners!==null) return;
  var sb=window._sb;
  if(!sb||!window._authProfile){ wgp.winners=[]; return; }
  sb.from('creatives').select('id,ad_name,product,persona,angle_type,format,roas,hook_rate,hook_short,status')
    .eq('brand',(typeof ACTIVE_BRAND!=='undefined')?ACTIVE_BRAND:'wellshave')
    .in('status',['Winner','Iterate']).order('roas',{ascending:false}).limit(6)
    .then(function(r){ wgp.winners=(r&&r.data)||[]; if(wgp.step==='winner') wgpRender(); })
    .catch(function(){ wgp.winners=[]; if(wgp.step==='winner') wgpRender(); });
}
function wgpLoadAngleHist(){
  wgp.angleHist=null;
  var sb=window._sb; var p=wgp.sel.persona;
  if(!sb||!window._authProfile||!p){ wgp.angleHist={}; return; }
  var merk=(typeof ACTIVE_BRAND!=='undefined')?ACTIVE_BRAND:'wellshave';
  var zoek='%'+p.replace(/[%,()]/g,'')+'%';
  var klaar=function(h){ wgp.angleHist=h; if(wgp.step==='angle') wgpRender(); };
  var leeg=function(){ return []; };

  /* Twee bronnen, twee verschillende vragen.
     hq_angle_learnings zegt wat een angle heeft OPGELEVERD: ROAS gewogen over
     advertenties heen (eerst spend en omzet optellen, dan pas delen), en of dat
     op genoeg data rust om iets te betekenen. Alleen beoordeelbare ads tellen mee.
     creatives zegt hoe vaak je hem GEPROBEERD hebt, ook zonder oordeel — anders
     ziet een angle die je gisteren getest hebt er onaangeroerd uit.
     Het eerste bepaalt de volgorde, het tweede vult hem aan. */
  Promise.all([
    sb.from('hq_angle_learnings').select('angle_type,roas,aantal_ads,winnaars,betrouwbaar')
      .eq('brand',merk).ilike('persona',zoek).limit(200)
      .then(function(r){ return (r&&r.data)||[]; }, leeg),
    sb.from('creatives').select('angle_type,roas').eq('brand',merk)
      .ilike('persona',zoek).limit(500)
      .then(function(r){ return (r&&r.data)||[]; }, leeg)
  ]).then(function(res){
    var h={};
    var vak=function(a){
      if(!h[a]) h[a]={ n:0, best:null, roas:null, ads:0, winnaars:0, betrouwbaar:false };
      return h[a];
    };
    res[1].forEach(function(row){
      if(!row.angle_type) return;
      var v=vak(row.angle_type); v.n++;
      if(row.roas!=null && (v.best==null || row.roas>v.best)) v.best=row.roas;
    });
    res[0].forEach(function(row){
      if(!row.angle_type) return;
      var v=vak(row.angle_type);
      v.roas=row.roas; v.ads=row.aantal_ads||0;
      v.winnaars=row.winnaars||0; v.betrouwbaar=!!row.betrouwbaar;
    });
    klaar(h);
  }).catch(function(){ klaar({}); });
}

/* ---------- braindump ---------- */
function wgpBd(){
  var el=document.getElementById('wgp-bd-text'); var status=document.getElementById('wgp-bd-status'); var btn=document.getElementById('wgp-bd-btn');
  var txt=el?el.value.trim():'';
  if(!txt){ if(status) status.textContent='Typ eerst je idee.'; return; }
  wgp.sel.bd=txt.length>40?txt.slice(0,40)+'...':txt;
  if(btn) btn.disabled=true; if(status) status.textContent='Fable vertaalt je idee naar een plan...';
  var personas=(state.personas||[]).map(function(p){return p.name+(p.description?(' ('+p.description.slice(0,60)+')'):'');}).join('; ');
  var products=(state.products||[]).map(function(p){return p.name;}).join('; ');
  var sys='Je vertaalt een losse creatieve ingeving van een marketeer naar een testplan voor een video-ad. Beschikbare producten: '+products+'. Beschikbare personas: '+personas+'. Beschikbare angles: '+CS_ANGLES.join(', ')+'. Beschikbare formats: '+CS_FORMATS.map(function(f){return f.name;}).join(', ')+'. Antwoord ALLEEN met strict JSON: {"product":"...of leeg","persona":"...of leeg","angle":"...of leeg","format":"...of leeg","scene":"opening-scene in 1 zin die het probleem TOONT, of leeg","toelichting":"1 zin"}. Kies bij voorkeur uit de gegeven lijsten (exacte naam); vul alleen in wat echt uit het idee volgt of er sterk uit afleidbaar is, laat de rest leeg.';
  fetchJsonWithRetry((PROXY_BASE+'/anthropic'),{
    method:'POST', headers:{'Content-Type':'application/json','anthropic-version':'2023-06-01'},
    body: JSON.stringify({ model: wgpModel(), max_tokens: 400, system: sys+brandProfileBlock(), messages:[{role:'user',content:txt}] })
  }).then(function(data){
    var t=wgClaudeTextOrNull(data)||'';
    var a=t.indexOf('{'); var b=t.lastIndexOf('}');
    if(a===-1||b===-1) throw new Error('geen JSON in antwoord');
    var p=JSON.parse(t.substring(a,b+1));
    wgpSet('product',p.product); wgpSet('persona',p.persona); wgpSet('angle',p.angle); wgpSet('format',p.format); wgpSet('scene',p.scene);
    if(btn) btn.disabled=false;
    wgpGo('plan');
    if(p.toelichting) toast('Fable: '+p.toelichting);
  }).catch(function(err){
    if(btn) btn.disabled=false;
    if(status) status.textContent='Kon Fable niet bereiken ('+err.message+'). Probeer opnieuw of loop de stappen zelf langs.';
  });
}

/* ---------- plan toepassen op het formulier + Theriot ---------- */
function wgpApplyAndWrite(){
  var hypoEl=document.getElementById('wgp-hypo');
  var hypo=hypoEl?hypoEl.value.trim():'';
  wgp.sel.hypo=hypo;
  var isVary=wgp.mode==='vary';
  var adname=isVary?String(wgp.sel.winnerName||'WS-VAR').replace(/-V\d+$/i,'')+'-V2':wgpAdName();
  window._swPlan={ ad_name:adname, hypothesis:hypo||null, test_variable:isVary?(wgp.sel.vary||null):'nieuwe combinatie', parent_id:wgp.sel.parentId||null, angle:wgp.sel.angle||null, format:wgp.sel.format||null };
  // formulier vullen
  if(typeof renderSwSelects==='function') renderSwSelects();
  var byName=function(selId,list,name){ if(!name) return; var el=document.getElementById(selId); if(!el) return; var hit=(list||[]).find(function(x){return x.name&&name&&x.name.toLowerCase()===name.toLowerCase();}); if(hit) el.value=hit.id; };
  byName('sw-product',state.products,wgp.sel.product);
  byName('sw-persona',state.personas,wgp.sel.persona);
  var awEl=document.getElementById('sw-awareness'); if(awEl){ var aw=wgpDeriveAw()[0]; awEl.value=WGP_AW_MAP[aw]||'problem'; }
  var angEl=document.getElementById('sw-angle'); if(angEl&&wgp.sel.angle){ angEl.value=wgp.sel.angle; if(angEl.value!==wgp.sel.angle) angEl.value=''; }
  var fmtEl=document.getElementById('sw-format'); if(fmtEl&&wgp.sel.format){ fmtEl.value=wgp.sel.format; if(fmtEl.value!==wgp.sel.format) fmtEl.value=''; }
  var parts=[];
  if(wgp.sel.scene) parts.push('Opening-scene (toon dit probleem in de eerste 3 seconden): '+wgp.sel.scene);
  if(wgp.sel.angle&&(!angEl||angEl.value==='')) parts.push('Angle: '+wgp.sel.angle);
  if(isVary) parts.push('Dit is een variatie op winner "'+(wgp.sel.winnerName||'')+'"; houd de kern gelijk en varieer alleen: '+(wgp.sel.vary||''));
  if(hypo) parts.push('Test-hypothese: '+hypo);
  var dirEl=document.getElementById('sw-direction');
  if(dirEl) dirEl.value=parts.join('\n')||dirEl.value||'Script volgens het plan uit Plan een test.';
  setSwMode('new');
  toast('Plan staat in het formulier, Theriot gaat schrijven');
  if(typeof swWriteScript==='function') swWriteScript();
}
function wgpSavePlanOnly(){
  var sb=window._sb;
  if(!sb||!window._authProfile||!window._authProfile.id){ toast('Log in op de live tool om het plan op te slaan',true); return; }
  if(window._userRole==='guest'){ toast('Alleen admin/member kan opslaan',true); return; }
  var hypoEl=document.getElementById('wgp-hypo'); var hypo=hypoEl?hypoEl.value.trim():'';
  var isVary=wgp.mode==='vary';
  var aw=wgpDeriveAw();
  var row={
    brand:(typeof ACTIVE_BRAND!=='undefined')?ACTIVE_BRAND:'wellshave',
    user_id:window._authProfile.id, user_email:window._authProfile.email||null, user_name:window._authProfile.full_name||window._authProfile.email||null,
    ad_name:isVary?String(wgp.sel.winnerName||'WS-VAR').replace(/-V\d+$/i,'')+'-V2':wgpAdName(),
    product:wgp.sel.product||null, persona:wgp.sel.persona||null, angle_type:wgp.sel.angle||null, format:wgp.sel.format||null,
    awareness_level:aw[0], creative_concept:wgp.sel.scene||null, media_type:'Video', status:'Not yet', source_type:'plan',
    hypothesis:hypo||null, test_variable:isVary?(wgp.sel.vary||null):'nieuwe combinatie', parent_id:wgp.sel.parentId||null
  };
  var doInsert=function(r2){ sb.from('creatives').insert(r2).then(function(r){
    if(r&&r.error){
      if(/column|schema cache/i.test(r.error.message)&&(r2.hypothesis!==undefined)){ var c=Object.assign({},r2); delete c.hypothesis; delete c.test_variable; delete c.parent_id; doInsert(c); return; }
      toast('Plan opslaan mislukt: '+r.error.message,true); return;
    }
    toast('Plan bewaard in de Creative Strategy-tabel (status Not yet)');
  }); };
  doInsert(row);
}

/* ---------- Fable spar-drawer ---------- */
var WGP_FABLE_BASIS='Je bent Fable, de creative-strategy sparringpartner in de Scriptwriter. Je denkt als Nick Theriot: awareness, sophistication, een variabele per test, show dont tell. Regels: antwoord in het Nederlands, maximaal 110 woorden, hoogstens EEN vraag per beurt, wees concreet en durf te kiezen. Als de keuze rijp is, eindig met een regel die begint met "ADVIES:" gevolgd door je aanbeveling in een zin. Geen em-dashes, geen opsommingstekens.';
var WGP_COACH={
  start:'Deze stap: kiezen tussen eigen idee, nieuwe combinatie (exploratie) of varieren op een winner (iteratie). Vuistregel: winner boven break-even met minder dan 3 variaties = eerst uitknijpen; anders exploreren waar de matrix leeg is.',
  braindump:'De gebruiker gooit een ruwe ingeving op tafel. Help hem het idee uitspreken en scherper maken: wat trekt hem eraan, welk beeld ziet hij, welke klant voelt hij erbij. Duw niet te snel naar structuur.',
  winner:'Help de juiste winner kiezen om uit te knijpen: weeg volume, leerwaarde en hoe verzadigd de variaties al zijn, niet alleen ROAS.',
  varywhat:'Help EEN variabele kiezen: hook rate laag = nieuwe hooks of opening-scene; hook sterk maar hold laag = body of format; alles sterk maar CTR laag = CTA/offer. Vraag naar de cijfers als je ze niet hebt.',
  product:'Scherp het probleem dat het script gaat tonen: zichtbaar te maken binnen 3 seconden en herkenbaar. Een goed probleem is een scene, geen abstractie.',
  persona:'Help de persona kiezen: grootste onbenutte pijnpunt, gat in de matrix, sterkste koopintentie.',
  angle:'Spar over de angle voor de gekozen persona, of stel een betere voor in echte klanttaal (als citaat). Toets: raakt hij het sterkste pijnpunt en past hij bij de awareness?',
  format:'Kies het format dat de angle het sterkst bewijst. Weeg ook productiekosten: wat kan er deze week echt gemaakt worden?',
  scene:'Bedenk de opening-scene die het probleem TOONT in de eerste 3 seconden. Filmisch: wat zie je in frame 1, wat is het geluid. Maximaal 2 scene-ideeen per beurt.',
  plan:'Scherp de hypothese aan tot een toetsbare uitspraak: als [verandering] bij [doelgroep], dan [verwachting met getal] op [primaire metric], omdat [reden]. Bewaak EEN variabele en een passende metric.'
};
function wgpContext(){
  var c='HUIDIGE KEUZES:\n'; var any=false;
  [['mode','Vertrekpunt'],['winnerName','Winner'],['vary','Te varieren'],['product','Product'],['persona','Persona'],['angle','Angle'],['format','Format'],['scene','Opening-scene']].forEach(function(k){ if(wgp.sel[k[0]]){ c+='- '+k[1]+': '+wgp.sel[k[0]]+'\n'; any=true; } });
  if(!any) c+='- nog niets gekozen\n';
  if(wgp.step==='persona'&&(state.personas||[]).length){ c+='BESCHIKBARE PERSONAS:\n'; (state.personas||[]).slice(0,10).forEach(function(p){ c+='- '+p.name+': '+((p.description||'').slice(0,90))+(p.pains&&p.pains.length?(' | pijn: '+p.pains.slice(0,3).join(', ')):'')+'\n'; }); }
  if(wgp.step==='angle'){
    var p=(state.personas||[]).find(function(x){return x.name===wgp.sel.persona;});
    if(p){ c+='PERSONA-DETAIL '+p.name.toUpperCase()+':\n'; if(p.pains&&p.pains.length) c+='- pijn: '+p.pains.join(' | ')+'\n'; if(p.desires&&p.desires.length) c+='- wensen: '+p.desires.join(' | ')+'\n'; if(p.objections&&p.objections.length) c+='- bezwaren: '+p.objections.join(' | ')+'\n'; }
    /* Fable krijgt hetzelfde beeld als het scherm, inclusief het onderscheid
       tussen een gewogen oordeel en een losse uitschieter. Anders adviseert hij
       op een ROAS van 5 die op één advertentie van één dag rust. */
    if(wgp.angleHist){
      c+='TESTHISTORIE ANGLES BIJ DEZE PERSONA:\n';
      Object.keys(wgp.angleHist).forEach(function(k){
        var v=wgp.angleHist[k];
        c+='- '+k+': '+v.n+'x getest';
        if(v.roas!=null) c+=', ROAS '+v.roas+' over '+v.ads+' beoordeelde ads'+(v.betrouwbaar?'':' (te dun voor een oordeel)');
        if(v.winnaars) c+=', '+v.winnaars+' winner';
        if(v.best!=null) c+=', beste losse ad ROAS '+v.best;
        c+='\n';
      });
    }
  }
  if(wgp.step==='plan'){ var el=document.getElementById('wgp-hypo'); if(el&&el.value) c+='HUIDIGE HYPOTHESE:\n'+el.value+'\n'; }
  return c;
}
function wgpFabToggle(){
  wgp.drawerOpen=!wgp.drawerOpen;
  var d=document.getElementById('wgp-drawer'); if(d) d.classList.toggle('open',wgp.drawerOpen);
  if(wgp.drawerOpen){ var st=document.getElementById('wgp-dr-stap'); if(st) st.textContent='Stap: '+(WGP_NAMEN[wgp.step]||wgp.step); wgpRenderChat(); if(!(wgp.chats[wgp.step]&&wgp.chats[wgp.step].length)) wgpKickoff(); }
}
function wgpRenderChat(){
  var box=document.getElementById('wgp-msgs'); if(!box) return;
  var list=wgp.chats[wgp.step]||[];
  box.innerHTML=list.map(function(m,idx){
    if(m.role==='think') return '<div class="wgp-msg think">'+wgpEsc(m.content)+'</div>';
    var cls=m.role==='assistant'?'ai':'user';
    var h='<div class="wgp-msg '+cls+'">'+wgpEsc(m.content);
    if(m.role==='assistant'&&idx===list.length-1&&(wgp.step==='scene'||wgp.step==='plan')) h+='<button class="wgp-overneem" onclick="wgpOverneem()">Neem over in de stap</button>';
    return h+'</div>';
  }).join('');
  box.scrollTop=box.scrollHeight;
}
function wgpOverneem(){
  var list=wgp.chats[wgp.step]||[]; var last=null;
  for(var i=list.length-1;i>=0;i--){ if(list[i].role==='assistant'){ last=list[i].content; break; } }
  if(!last) return;
  var advies=last; var m=last.match(/ADVIES:\s*([\s\S]+)/); if(m) advies=m[1].trim();
  if(wgp.step==='scene'){ var el=document.getElementById('wgp-eigen-scene'); if(el) el.value=advies; wgp.sel.scene=advies; wgpRender(); }
  else if(wgp.step==='plan'){ var h=document.getElementById('wgp-hypo'); if(h) h.value=advies; wgp.sel.hypo=advies; }
}
function wgpPush(role,content){ if(!wgp.chats[wgp.step]) wgp.chats[wgp.step]=[]; wgp.chats[wgp.step].push({role:role,content:content}); wgpRenderChat(); }
function wgpKickoff(){ wgpAsk('Ik sta bij deze stap. Trap af: kijk naar mijn keuzes, geef je scherpste advies voor deze stap en stel je eerste vraag.',true); }
function wgpSend(){ var el=document.getElementById('wgp-in'); var t=el?el.value.trim():''; if(!t||wgp.busy) return; el.value=''; wgpPush('user',t); wgpAsk(t,false); }
function wgpAsk(userText,isKickoff){
  if(wgp.busy) return; wgp.busy=true;
  var sb=document.getElementById('wgp-send'); if(sb) sb.disabled=true;
  if(!wgp.chats[wgp.step]) wgp.chats[wgp.step]=[];
  wgp.chats[wgp.step].push({role:'think',content:'Fable denkt na...'}); wgpRenderChat();
  var msgs=(wgp.chats[wgp.step]||[]).filter(function(m){return m.role==='user'||m.role==='assistant';}).map(function(m){return {role:m.role,content:m.content};});
  msgs.push({role:'user',content:userText+'\n\n'+wgpContext()});
  fetchJsonWithRetry((PROXY_BASE+'/anthropic'),{
    method:'POST', headers:{'Content-Type':'application/json','anthropic-version':'2023-06-01'},
    body: JSON.stringify({ model:wgpModel(), max_tokens:500, system:WGP_FABLE_BASIS+brandProfileBlock()+'\n\nSTAP-INSTRUCTIE: '+(WGP_COACH[wgp.step]||''), messages:msgs })
  }).then(function(data){
    wgp.chats[wgp.step]=wgp.chats[wgp.step].filter(function(m){return m.role!=='think';});
    var text=(wgClaudeTextOrNull(data)||'').trim()||null;
    if(!text) throw new Error('leeg antwoord');
    wgpPush('assistant',text);
  }).catch(function(err){
    wgp.chats[wgp.step]=wgp.chats[wgp.step].filter(function(m){return m.role!=='think';});
    wgpPush('assistant','Kon de team-server niet bereiken ('+err.message+'). Probeer het zo nog eens.');
  }).finally(function(){ wgp.busy=false; var sb2=document.getElementById('wgp-send'); if(sb2) sb2.disabled=false; });
}

/* ===== Creative Strategy master-tabel (v5.01): spiegelt de Test Tracker, per-rij in Supabase ===== */
var CS_ANGLES = ['Problem-Solution','Benefits-Driven','Storytelling / Narrative','Social Proof / Reviews','Transformation / Before-After','Comparison / Anti-X','Authority / Expert','Curiosity / Intrigue','Negative / Pain Agitation','FOMO / Scarcity'];
var CS_FORMATS = [
  { name: 'UGC Talking Head Testimonial', cat: 'Video' },
  { name: 'UGC Story Time / Day in the Life', cat: 'Video' },
  { name: 'UGC Demo / How-To', cat: 'Video' },
  { name: 'Studio / Polished Brand Video', cat: 'Video' },
  { name: 'Founder Story / Origin Video', cat: 'Video' },
  { name: 'Before & After / Transformation', cat: 'Video' },
  { name: 'Split Screen Comparison', cat: 'Video' },
  { name: 'Animated / Motion Graphics', cat: 'Video' },
  { name: 'Single Image + Text Overlay', cat: 'Static' },
  { name: 'Carousel (Meta / Instagram)', cat: 'Static' },
  { name: 'Meme / Cultural Reference', cat: 'Static' },
  { name: 'Quote Card / Review Static', cat: 'Static' },
  { name: 'Podcast Host-Read Ad', cat: 'Audio' },
  { name: 'Podcast Pre-Recorded Spot', cat: 'Audio' },
  { name: 'Spotify / Streaming Audio Ad', cat: 'Audio' },
  { name: 'Native Article / Advertorial', cat: 'Other' },
  { name: 'Influencer Partnership', cat: 'Other' }
];
var CS_STATUSES = ['To Test','Live','Winner','Iterate','Killed','Not yet'];
var CS_AWARENESS = ['Unaware','Problem Aware','Solution Aware','Product Aware','Most Aware'];
var _cs = { page: 0, pageSize: 50, total: 0, rows: [], inited: false, editing: null, editingIsNew: false };

function csSb() { return (window._sb && window._authProfile && window._authProfile.id) ? window._sb : null; }
function csCanWrite() { return window._userRole === 'admin' || window._userRole === 'member'; }
function csBrand() { return (typeof ACTIVE_BRAND !== 'undefined') ? ACTIVE_BRAND : 'wellshave'; }
function csAwLabel(v) { var m = { unaware: 'Unaware', problem: 'Problem Aware', solution: 'Solution Aware', product: 'Product Aware', most: 'Most Aware' }; return m[v] || v || ''; }
function csFormatCat(name) { for (var i = 0; i < CS_FORMATS.length; i++) { if (CS_FORMATS[i].name === name) return CS_FORMATS[i].cat; } return ''; }
function csEsc(t) { return escapeHtml(t == null ? '' : String(t)); }
function csNum(v, dec) { if (v == null || v === '') return ''; var n = Number(v); if (isNaN(n)) return ''; return n.toLocaleString('nl-NL', { minimumFractionDigits: 0, maximumFractionDigits: (dec == null ? 2 : dec) }); }

/* Script-bibliotheek -> creatives rij (bij bewaren van een script) */
function pushCreativeRow(item) {
  var sb = csSb();
  if (!sb || !csCanWrite()) return;
  var meta = item.meta || {}; var s = item.script || {}; var info = s.info || {};
  var hook = '';
  try { hook = (s.hooks && s.hooks[0] && (s.hooks[0].aroll || s.hooks[0].tekst)) || ''; } catch (e) {}
  var row = {
    brand: csBrand(),
    user_id: window._authProfile.id,
    user_email: window._authProfile.email || null,
    user_name: window._authProfile.full_name || window._authProfile.email || null,
    ad_name: item.name || 'Script',
    product: meta.product || null,
    awareness_level: csAwLabel(meta.awareness) || null,
    angle_type: meta.angle || null,
    marketing_angle: info.angle || null,
    desires: info.emotie_desire || null,
    format: meta.format || null,
    creative_concept: info.mechanisme_belief_shift || null,
    media_type: meta.format ? (csFormatCat(meta.format) || 'Video') : 'Video',
    hook_short: hook ? String(hook).slice(0, 300) : null,
    persona: meta.persona || info.persona || null,
    status: 'To Test',
    source_type: 'script',
    script: s
  };
  var plan = window._swPlan || null;
  if (plan) {
    if (plan.ad_name) row.ad_name = plan.ad_name;
    if (plan.angle && !row.angle_type) row.angle_type = plan.angle;
    if (plan.format && !row.format) row.format = plan.format;
    row.hypothesis = plan.hypothesis || null;
    row.test_variable = plan.test_variable || null;
    row.parent_id = plan.parent_id || null;
  }
  var doIns = function (r2) {
    sb.from('creatives').insert(r2).then(function (r) {
      if (r && r.error) {
        if (/column|schema cache/i.test(r.error.message) && r2.hypothesis !== undefined) {
          var c = Object.assign({}, r2); delete c.hypothesis; delete c.test_variable; delete c.parent_id;
          doIns(c); return;
        }
        console.warn('creatives insert', r.error.message); toast('Niet in Creative Strategy-tabel gekomen: ' + r.error.message, true);
      }
      else { toast('Ook als rij in de Creative Strategy-tabel gezet (status To Test)'); window._swPlan = null; }
    }).catch(function (e) { console.warn('creatives insert', e); });
  };
  doIns(row);
}

function csInitFilters() {
  if (_cs.inited) return;
  _cs.inited = true;
  var a = document.getElementById('cs-f-angle');
  if (a) CS_ANGLES.forEach(function (x) { var o = document.createElement('option'); o.value = x; o.textContent = x; a.appendChild(o); });
  var f = document.getElementById('cs-f-format');
  if (f) CS_FORMATS.forEach(function (x) { var o = document.createElement('option'); o.value = x.name; o.textContent = x.name; f.appendChild(o); });
  ['cs-f-q', 'cs-f-product', 'cs-f-persona'].forEach(function (id) {
    var el = document.getElementById(id);
    if (el) el.addEventListener('keydown', function (ev) { if (ev.key === 'Enter') csApplyFilters(); });
  });
  ['cs-f-status', 'cs-f-angle', 'cs-f-format'].forEach(function (id) {
    var el = document.getElementById(id);
    if (el) el.addEventListener('change', function () { csApplyFilters(); });
  });
}

function renderCreatives() {
  csInitFilters();
  var note = document.getElementById('cs-login-note');
  var body = document.getElementById('cs-body');
  var sb = csSb();
  if (!sb) {
    if (note) { note.style.display = 'block'; }
    if (body) body.style.display = 'none';
    return;
  }
  if (note) note.style.display = 'none';
  if (body) body.style.display = 'block';
  var imp = document.getElementById('cs-btn-import');
  var nw = document.getElementById('cs-btn-new');
  if (imp) imp.style.display = csCanWrite() ? '' : 'none';
  if (nw) nw.style.display = csCanWrite() ? '' : 'none';
  // Het besluit eerst, de tabel eronder. Twee losse aanroepen, want als het
  // dagbesluit omvalt hoort de tabel gewoon te laden -- en andersom.
  if (typeof dbsFetch === 'function') dbsFetch();
  csFetch();
}

function csFilters() {
  var g = function (id) { var el = document.getElementById(id); return el ? (el.value || '').trim() : ''; };
  return { status: g('cs-f-status'), angle: g('cs-f-angle'), format: g('cs-f-format'), q: g('cs-f-q'), product: g('cs-f-product'), persona: g('cs-f-persona') };
}

function csApplyFilters() { _cs.page = 0; csFetch(); }
function csResetFilters() {
  ['cs-f-status', 'cs-f-angle', 'cs-f-format', 'cs-f-q', 'cs-f-product', 'cs-f-persona'].forEach(function (id) { var el = document.getElementById(id); if (el) el.value = ''; });
  csApplyFilters();
}

function csFetch() {
  var sb = csSb(); if (!sb) return;
  var wrap = document.getElementById('cs-table-wrap');
  if (wrap && !_cs.rows.length) wrap.innerHTML = '<div class="loading-card">Creatives laden van de teamserver...</div>';
  var f = csFilters();
  var q = sb.from('creatives').select('*', { count: 'exact' }).eq('brand', csBrand());
  if (f.status) q = q.eq('status', f.status);
  if (f.angle) q = q.eq('angle_type', f.angle);
  if (f.format) q = q.eq('format', f.format);
  if (f.product) q = q.ilike('product', '%' + f.product + '%');
  if (f.persona) q = q.ilike('persona', '%' + f.persona + '%');
  if (f.q) {
    var s = f.q.replace(/[,()]/g, ' ').trim();
    if (s) q = q.or('ad_name.ilike.%' + s + '%,hook_short.ilike.%' + s + '%,notes.ilike.%' + s + '%,marketing_angle.ilike.%' + s + '%,creative_concept.ilike.%' + s + '%');
  }
  q = q.order('created_at', { ascending: false }).range(_cs.page * _cs.pageSize, (_cs.page + 1) * _cs.pageSize - 1);
  q.then(function (r) {
    if (r && r.error) {
      console.warn('creatives select', r.error.message);
      if (wrap) wrap.innerHTML = '<div class="loading-card" style="color:#bd0f0f;">Laden mislukt: ' + csEsc(r.error.message) + '.<br>Is het SQL-script supabase-creatives-master.sql al uitgevoerd in Supabase?</div>';
      return;
    }
    _cs.rows = (r && r.data) || [];
    _cs.total = (r && r.count) || 0;
    csRenderTable();
  }).catch(function (e) { console.warn('creatives select', e); if (wrap) wrap.innerHTML = '<div class="loading-card" style="color:#bd0f0f;">Laden mislukt: ' + csEsc(e.message || e) + '</div>'; });
}

function csBadge(status) {
  var map = { 'To Test': 'cs-b-totest', 'Live': 'cs-b-live', 'Winner': 'cs-b-winner', 'Iterate': 'cs-b-iterate', 'Killed': 'cs-b-killed', 'Not yet': 'cs-b-notyet' };
  var cls = map[status] || 'cs-b-totest';
  return '<span class="cs-badge ' + cls + '">' + csEsc(status || 'To Test') + '</span>';
}

function csRenderTable() {
  var wrap = document.getElementById('cs-table-wrap');
  var pager = document.getElementById('cs-pager');
  var sum = document.getElementById('cs-summary');
  if (!wrap) return;
  if (sum) sum.textContent = _cs.total + ' creative' + (_cs.total === 1 ? '' : 's') + ' in de master-tabel' + (csFiltersActive() ? ' (gefilterd)' : '');
  if (!_cs.rows.length) {
    wrap.innerHTML = '<div class="slib-empty">Nog geen creatives gevonden. Bewaar een script in de Scriptwriter, voeg zelf een rij toe, of importeer de bestaande rijen uit de Creative Strategy Map.</div>';
    if (pager) pager.innerHTML = '';
    return;
  }
  var h = '<table class="cs-table"><thead><tr><th>Ad</th><th>Product</th><th>Angle</th><th>Format</th><th>Persona</th><th>Status</th><th class="num">Score</th><th class="num">ROAS</th><th class="num">CTR</th><th class="num">Hook rate</th><th>Live sinds</th></tr></thead><tbody>';
  _cs.rows.forEach(function (row) {
    h += '<tr onclick="csOpenDetail(' + row.id + ')">'
      + '<td class="cs-name">' + csEsc(row.ad_name || '-') + (row.script ? ' <span class="cs-scripttag" title="Script gekoppeld">script</span>' : '') + '</td>'
      + '<td>' + csEsc(row.product || '') + '</td>'
      + '<td>' + csEsc(row.angle_type || '') + '</td>'
      + '<td>' + csEsc(row.format || '') + '</td>'
      + '<td>' + csEsc(row.persona || '') + '</td>'
      + '<td>' + csBadge(row.status) + '</td>'
      + '<td class="num">' + csNum(row.score, 1) + '</td>'
      + '<td class="num">' + csNum(row.roas) + '</td>'
      + '<td class="num">' + (row.ctr == null ? '' : csNum(row.ctr) + '%') + '</td>'
      + '<td class="num">' + (row.hook_rate == null ? '' : csNum(row.hook_rate) + '%') + '</td>'
      + '<td>' + csEsc(row.date_live || '') + '</td>'
      + '</tr>';
  });
  h += '</tbody></table>';
  wrap.innerHTML = h;
  if (pager) {
    var from = _cs.page * _cs.pageSize + 1;
    var to = Math.min(_cs.total, (_cs.page + 1) * _cs.pageSize);
    var maxPage = Math.max(0, Math.ceil(_cs.total / _cs.pageSize) - 1);
    pager.innerHTML = '<button class="btn btn-small btn-ghost" ' + (_cs.page <= 0 ? 'disabled' : '') + ' onclick="csPrevPage()">Vorige</button>'
      + '<span class="cs-pageinfo">' + from + ' t/m ' + to + ' van ' + _cs.total + '</span>'
      + '<button class="btn btn-small btn-ghost" ' + (_cs.page >= maxPage ? 'disabled' : '') + ' onclick="csNextPage()">Volgende</button>';
  }
}

function csFiltersActive() { var f = csFilters(); return !!(f.status || f.angle || f.format || f.q || f.product || f.persona); }
function csPrevPage() { if (_cs.page > 0) { _cs.page--; csFetch(); } }
function csNextPage() { if ((_cs.page + 1) * _cs.pageSize < _cs.total) { _cs.page++; csFetch(); } }

/* ---------- detail / bewerken ---------- */
function csOpenDetail(id) {
  var row = null;
  for (var i = 0; i < _cs.rows.length; i++) { if (_cs.rows[i].id === id) { row = _cs.rows[i]; break; } }
  if (!row) return;
  _cs.editing = JSON.parse(JSON.stringify(row));
  _cs.editingIsNew = false;
  csRenderDetail();
}

function csNewRow() {
  if (!csCanWrite()) { toast('Alleen admin/member kan rijen toevoegen', true); return; }
  _cs.editing = { status: 'To Test', source_type: 'manual' };
  _cs.editingIsNew = true;
  csRenderDetail();
}

/* De huidige waarde hoort er altijd bij te staan, ook als hij niet in de lijst
   voorkomt. Zonder deze regel toont het veld leeg bij een waarde als
   'comparison' of 'premium', en overschrijft de eerstvolgende Opslaan die
   waarde met niets — stille dataverlies bij iemand die alleen een score
   invulde. Vrije waarden zijn toegestaan; dan moeten ze ook overleven. */
function csSelOpts(list, cur) {
  var h = '<option value=""></option>';
  var namen = list.map(function (x) { return (typeof x === 'string') ? x : x.name; });
  if (cur && namen.indexOf(cur) === -1) {
    h += '<option value="' + csEsc(cur) + '" selected>' + csEsc(cur) + ' (eigen waarde)</option>';
  }
  namen.forEach(function (v) { h += '<option value="' + csEsc(v) + '"' + (v === cur ? ' selected' : '') + '>' + csEsc(v) + '</option>'; });
  return h;
}

function csRenderDetail() {
  var box = document.getElementById('cs-detail');
  if (!box) return;
  var r = _cs.editing || {};
  var ro = !csCanWrite();
  var dis = ro ? ' disabled' : '';
  var fld = function (label, id, val, type, span) {
    return '<div class="field' + (span ? ' cs-span2' : '') + '"><label class="label">' + label + '</label><input id="' + id + '" type="' + (type || 'text') + '" value="' + csEsc(val == null ? '' : val) + '"' + dis + '></div>';
  };
  var ta = function (label, id, val, span) {
    return '<div class="field' + (span ? ' cs-span2' : '') + '"><label class="label">' + label + '</label><textarea id="' + id + '" rows="2"' + dis + '>' + csEsc(val == null ? '' : val) + '</textarea></div>';
  };
  var h = '<div class="cs-detail-card">';
  h += '<div class="cs-detail-head"><strong>' + (_cs.editingIsNew ? 'Nieuwe creative' : csEsc(r.ad_name || 'Creative')) + '</strong>'
    + (r.user_name ? '<span class="cs-maker">door ' + csEsc(r.user_name) + '</span>' : '')
    + '<button class="btn btn-small btn-ghost" style="margin-left:auto;" onclick="csCloseDetail()">Sluiten</button></div>';
  h += '<div class="cs-sec-title">Plan</div><div class="cs-grid">';
  h += fld('Ad name', 'csd-ad_name', r.ad_name);
  h += fld('Product', 'csd-product', r.product);
  h += '<div class="field"><label class="label">Awareness level</label><select id="csd-awareness_level"' + dis + '>' + csSelOpts(CS_AWARENESS, r.awareness_level) + '</select></div>';
  h += '<div class="field"><label class="label">Angle type</label><select id="csd-angle_type"' + dis + '>' + csSelOpts(CS_ANGLES, r.angle_type) + '</select></div>';
  h += ta('Marketing angle', 'csd-marketing_angle', r.marketing_angle, true);
  h += ta('Desires', 'csd-desires', r.desires, true);
  h += '<div class="field"><label class="label">Format</label><select id="csd-format"' + dis + '>' + csSelOpts(CS_FORMATS, r.format) + '</select></div>';
  h += '<div class="field"><label class="label">Media type</label><select id="csd-media_type"' + dis + '>' + csSelOpts(['Video', 'Static', 'Audio', 'Other'], r.media_type) + '</select></div>';
  h += ta('Creative concept', 'csd-creative_concept', r.creative_concept, true);
  h += ta('Hook (short)', 'csd-hook_short', r.hook_short, true);
  h += fld('Channel', 'csd-channel', r.channel);
  h += fld('Audience', 'csd-audience', r.audience);
  h += fld('Persona', 'csd-persona', r.persona);
  h += '</div>';
  h += '<div class="cs-sec-title">Live &amp; performance</div><div class="cs-grid cs-grid-nums">';
  h += fld('Date live', 'csd-date_live', r.date_live, 'date');
  h += fld('Budget', 'csd-budget', r.budget, 'number');
  h += fld('Impressions', 'csd-impressions', r.impressions, 'number');
  h += fld('Hook rate %', 'csd-hook_rate', r.hook_rate, 'number');
  h += fld('Hold rate %', 'csd-hold_rate', r.hold_rate, 'number');
  h += fld('CTR %', 'csd-ctr', r.ctr, 'number');
  h += fld('CPM', 'csd-cpm', r.cpm, 'number');
  h += fld('CPC', 'csd-cpc', r.cpc, 'number');
  h += fld('Conversions', 'csd-conversions', r.conversions, 'number');
  h += fld('CVR %', 'csd-cvr', r.cvr, 'number');
  h += fld('CPA', 'csd-cpa', r.cpa, 'number');
  h += fld('AOV', 'csd-aov', r.aov, 'number');
  h += fld('ROAS', 'csd-roas', r.roas, 'number');
  h += fld('Break-even ROAS', 'csd-breakeven_roas', r.breakeven_roas, 'number');
  h += fld('Target ROAS', 'csd-target_roas', r.target_roas, 'number');
  h += '</div>';
  h += '<div class="cs-sec-title">Beslissing</div><div class="cs-grid">';
  h += '<div class="field"><label class="label">Status</label><select id="csd-status"' + dis + '>' + csSelOpts(CS_STATUSES, r.status || 'To Test') + '</select></div>';
  h += fld('Score (1-10)', 'csd-score', r.score, 'number');
  h += ta('Next step', 'csd-next_step', r.next_step, true);
  h += ta('Notes', 'csd-notes', r.notes, true);
  h += fld('Creatives link', 'csd-creatives_link', r.creatives_link, 'text', true);
  h += '</div>';
  h += '<div class="cs-detail-actions">';
  if (!ro) h += '<button class="btn" onclick="csSaveDetail()">' + (_cs.editingIsNew ? 'Rij toevoegen' : 'Wijzigingen opslaan') + '</button>';
  if (r.script) h += '<button class="btn btn-small btn-ghost" onclick="csToggleScript()">Bekijk gekoppeld script</button>';
  if (!ro && !_cs.editingIsNew) h += '<button class="btn btn-small btn-ghost btn-danger" onclick="csDeleteRow()">Verwijder rij</button>';
  h += '</div>';
  h += '<div id="cs-script-view" style="display:none;"></div>';
  h += '</div>';
  box.innerHTML = h;
  box.style.display = 'block';
  try { box.scrollIntoView({ behavior: 'smooth', block: 'nearest' }); } catch (e) {}
}

function csToggleScript() {
  var v = document.getElementById('cs-script-view');
  if (!v) return;
  if (v.style.display === 'none') {
    try { v.innerHTML = buildSwScriptHtml(_cs.editing.script); } catch (e) { v.innerHTML = '<div class="loading-card">Script kon niet worden weergegeven.</div>'; }
    v.style.display = 'block';
  } else { v.style.display = 'none'; }
}

function csCloseDetail() {
  var box = document.getElementById('cs-detail');
  if (box) { box.style.display = 'none'; box.innerHTML = ''; }
  _cs.editing = null;
}

function csReadDetail() {
  var g = function (id) { var el = document.getElementById('csd-' + id); return el ? el.value.trim() : ''; };
  var n = function (id) { var v = g(id); if (v === '') return null; var x = Number(String(v).replace(',', '.')); return isNaN(x) ? null : x; };
  var t = function (id) { var v = g(id); return v === '' ? null : v; };
  return {
    ad_name: t('ad_name'), product: t('product'), awareness_level: t('awareness_level'), angle_type: t('angle_type'),
    marketing_angle: t('marketing_angle'), desires: t('desires'), format: t('format'), media_type: t('media_type'),
    creative_concept: t('creative_concept'), hook_short: t('hook_short'), channel: t('channel'), audience: t('audience'), persona: t('persona'),
    date_live: t('date_live'), budget: n('budget'), impressions: n('impressions'), hook_rate: n('hook_rate'), hold_rate: n('hold_rate'),
    ctr: n('ctr'), cpm: n('cpm'), cpc: n('cpc'), conversions: n('conversions'), cvr: n('cvr'), cpa: n('cpa'), aov: n('aov'),
    roas: n('roas'), breakeven_roas: n('breakeven_roas'), target_roas: n('target_roas'),
    score: n('score'), status: t('status') || 'To Test', next_step: t('next_step'), notes: t('notes'), creatives_link: t('creatives_link')
  };
}

function csSaveDetail() {
  var sb = csSb(); if (!sb || !csCanWrite()) return;
  var vals = csReadDetail();
  if (!vals.ad_name) { toast('Geef de creative een ad name', true); return; }
  if (_cs.editingIsNew) {
    vals.brand = csBrand();
    vals.user_id = window._authProfile.id;
    vals.user_email = window._authProfile.email || null;
    vals.user_name = window._authProfile.full_name || window._authProfile.email || null;
    vals.source_type = 'manual';
    sb.from('creatives').insert(vals).then(function (r) {
      if (r && r.error) { toast('Toevoegen mislukt: ' + r.error.message, true); return; }
      toast('Creative toegevoegd aan de master-tabel');
      csCloseDetail(); csFetch();
    });
  } else {
    sb.from('creatives').update(vals).eq('id', _cs.editing.id).then(function (r) {
      if (r && r.error) { toast('Opslaan mislukt: ' + r.error.message, true); return; }
      toast('Creative bijgewerkt');
      csCloseDetail(); csFetch();
    });
  }
}

function csDeleteRow() {
  var sb = csSb(); if (!sb || !csCanWrite() || !_cs.editing || !_cs.editing.id) return;
  var ok = false;
  try { ok = window.confirm('Deze rij definitief verwijderen uit de master-tabel?'); } catch (e) { ok = true; }
  if (!ok) return;
  sb.from('creatives').delete().eq('id', _cs.editing.id).then(function (r) {
    if (r && r.error) { toast('Verwijderen mislukt: ' + r.error.message, true); return; }
    toast('Rij verwijderd');
    csCloseDetail(); csFetch();
  });
}

/* ---------- import uit de Creative Strategy Map (plak TSV/CSV met kopregel) ---------- */
function csToggleImport() {
  var p = document.getElementById('cs-import-panel');
  if (p) p.style.display = (p.style.display === 'none' || !p.style.display) ? 'block' : 'none';
}

function csHeaderKey(h) { return String(h || '').toLowerCase().replace(/[^a-z0-9]/g, ''); }
var CS_HEADER_MAP = {
  adname: 'ad_name', product: 'product', awarenesslevel: 'awareness_level', angletype: 'angle_type',
  marketingangle: 'marketing_angle', desires: 'desires', format: 'format', creativeconcept: 'creative_concept',
  mediatype: 'media_type', hookshort: 'hook_short', hook: 'hook_short', channel: 'channel', audience: 'audience',
  persona: 'persona', datelive: 'date_live', budget: 'budget', impressions: 'impressions', hookrate: 'hook_rate',
  holdrate: 'hold_rate', ctr: 'ctr', cpm: 'cpm', cpc: 'cpc', conversions: 'conversions', cvr: 'cvr', cpa: 'cpa',
  aov: 'aov', roas: 'roas', breakevenroas: 'breakeven_roas', targetroas: 'target_roas', score: 'score',
  score110: 'score', status: 'status', nextstep: 'next_step', notes: 'notes', creativeslink: 'creatives_link'
};
var CS_NUM_COLS = ['budget', 'impressions', 'hook_rate', 'hold_rate', 'ctr', 'cpm', 'cpc', 'conversions', 'cvr', 'cpa', 'aov', 'roas', 'breakeven_roas', 'target_roas', 'score'];

function csParseNum(v) {
  if (v == null) return null;
  var s = String(v).replace(/[€$%\s]/g, '').trim();
  if (!s || s === '-') return null;
  if (s.indexOf(',') !== -1 && s.indexOf('.') !== -1) { s = s.replace(/\./g, '').replace(',', '.'); }
  else { s = s.replace(',', '.'); }
  var n = Number(s);
  return isNaN(n) ? null : n;
}

function csParseDate(v) {
  if (!v) return null;
  var s = String(v).trim();
  var m = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (m) return m[1] + '-' + m[2] + '-' + m[3];
  m = s.match(/^(\d{1,2})[-\/](\d{1,2})[-\/](\d{4})/);
  if (m) { var d = ('0' + m[1]).slice(-2), mo = ('0' + m[2]).slice(-2); return m[3] + '-' + mo + '-' + d; }
  return null;
}

function csSplitLine(line, sep) {
  if (sep === '\t') return line.split('\t');
  var out = [], cur = '', inQ = false;
  for (var i = 0; i < line.length; i++) {
    var c = line[i];
    if (inQ) {
      if (c === '"') { if (line[i + 1] === '"') { cur += '"'; i++; } else { inQ = false; } }
      else cur += c;
    } else {
      if (c === '"') inQ = true;
      else if (c === sep) { out.push(cur); cur = ''; }
      else cur += c;
    }
  }
  out.push(cur);
  return out;
}

function csImport() {
  var sb = csSb();
  if (!sb || !csCanWrite()) { toast('Alleen admin/member kan importeren', true); return; }
  var el = document.getElementById('cs-import-text');
  var status = document.getElementById('cs-import-status');
  var raw = el ? el.value : '';
  if (!raw.trim()) { toast('Plak eerst de rijen uit de Test Tracker (met kopregel)', true); return; }
  var lines = raw.replace(/\r/g, '').split('\n').filter(function (l) { return l.trim() !== ''; });
  if (lines.length < 2) { toast('Ik zie geen datarijen onder de kopregel', true); return; }
  var sep = lines[0].indexOf('\t') !== -1 ? '\t' : (lines[0].indexOf(';') !== -1 ? ';' : ',');
  var headers = csSplitLine(lines[0], sep).map(csHeaderKey);
  var cols = headers.map(function (hk) { return CS_HEADER_MAP[hk] || null; });
  if (cols.indexOf('ad_name') === -1) { toast('Kopregel niet herkend: er moet minstens een Ad Name-kolom in zitten', true); return; }
  var rows = [];
  for (var i = 1; i < lines.length; i++) {
    var cells = csSplitLine(lines[i], sep);
    var row = { brand: csBrand(), source_type: 'import', status: 'To Test' };
    var has = false;
    for (var c = 0; c < cols.length; c++) {
      var col = cols[c]; if (!col) continue;
      var val = (cells[c] == null ? '' : String(cells[c])).trim();
      if (val === '') continue;
      if (col === 'date_live') { var dv = csParseDate(val); if (dv) { row.date_live = dv; has = true; } continue; }
      if (CS_NUM_COLS.indexOf(col) !== -1) { var nv = csParseNum(val); if (nv !== null) { row[col] = nv; has = true; } continue; }
      row[col] = val; has = true;
    }
    if (has && row.ad_name) rows.push(row);
  }
  if (!rows.length) { toast('Geen bruikbare rijen gevonden (elke rij heeft een Ad Name nodig)', true); return; }
  if (status) status.textContent = rows.length + ' rijen klaar, importeren...';
  var batches = [];
  for (var b = 0; b < rows.length; b += 100) batches.push(rows.slice(b, b + 100));
  var done = 0, failed = 0;
  var next = function () {
    if (!batches.length) {
      if (status) status.textContent = 'Klaar: ' + done + ' rijen geimporteerd' + (failed ? (', ' + failed + ' mislukt') : '');
      toast(done + ' creatives geimporteerd in de master-tabel' + (failed ? (', ' + failed + ' mislukt') : ''));
      if (el && !failed) el.value = '';
      csApplyFilters();
      return;
    }
    var batch = batches.shift();
    sb.from('creatives').insert(batch).then(function (r) {
      if (r && r.error) { console.warn('import batch', r.error.message); failed += batch.length; }
      else done += batch.length;
      if (status) status.textContent = done + ' van ' + rows.length + ' rijen geimporteerd...';
      next();
    }).catch(function () { failed += batch.length; next(); });
  };
  next();
}

function saveCurrentScript() {
  if (!state.lastScript) { toast('Geen script om te bewaren', true); return; }
  const ctx = state.lastScriptContext || { type: 'new', meta: {} };
  const info = state.lastScript.info || {};
  const baseName = (ctx.meta && ctx.meta.product) ? ctx.meta.product : (info.persona || 'Script');
  const defName = (window._swPlan && window._swPlan.ad_name) ? window._swPlan.ad_name : (baseName + ' , ' + (ctx.type === 'iterate' ? 'iteratie' : 'nieuw'));
  let name = defName;
  try { const r = window.prompt('Naam voor dit script:', defName); if (r === null) return; if (r.trim()) name = r.trim(); } catch (e) {}
  const item = {
    id: 'scr-' + Date.now() + '-' + Math.random().toString(36).slice(2, 6),
    saved_at: Date.now(),
    brand: (typeof ACTIVE_BRAND !== 'undefined') ? ACTIVE_BRAND : '',
    type: ctx.type || 'new',
    name: name,
    script: state.lastScript,
    source: ctx.source || null,
    meta: ctx.meta || {}
  };
  state.scriptLibrary = state.scriptLibrary || [];
  state.scriptLibrary.unshift(item);
  if (!saveScriptLibrary()) { toast('Opslaan mislukt, mogelijk te groot', true); return; }
  toast('Script bewaard in de script-bibliotheek');
  try { if (typeof pushCreativeRow === 'function') pushCreativeRow(item); } catch (e) { console.warn('creatives push', e); }
  if (typeof renderScriptLibrary === 'function' && document.getElementById('main-tab-scripts') && document.getElementById('main-tab-scripts').style.display !== 'none') renderScriptLibrary();
}
function renderScriptLibrary() {
  const el = document.getElementById('scriptlib-list');
  if (!el) return;
  const items = (state.scriptLibrary || []);
  if (!items.length) { el.innerHTML = '<div class="slib-empty">Nog geen scripts bewaard. Schrijf of itereer een script in de Scriptwriter en klik op Bewaar in script-bibliotheek.</div>'; return; }
  el.innerHTML = items.map(function(it){
    const d = new Date(it.saved_at || Date.now());
    const date = d.toLocaleDateString('nl-NL') + ' ' + d.toLocaleTimeString('nl-NL', { hour: '2-digit', minute: '2-digit' });
    const meta = it.meta || {};
    const badge = (it.type === 'iterate') ? '<span class="slib-badge iter">Iteratie</span>' : '<span class="slib-badge new">Nieuw</span>';
    const sub = [];
    if (meta.product) sub.push(meta.product);
    if (it.type === 'iterate') sub.push('uit een getest script met cijfers');
    return '<div class="slib-item"><div><div class="slib-title">' + escapeHtml(it.name || 'Script') + badge + '</div><div class="slib-meta">' + escapeHtml(date) + (sub.length ? (' , ' + escapeHtml(sub.join(' , '))) : '') + '</div></div>'
      + '<div class="slib-actions"><button class="btn btn-small" onclick="viewScriptLibraryItem(\'' + it.id + '\')">Bekijk</button><button class="btn btn-small btn-ghost btn-danger" onclick="deleteScriptLibraryItem(\'' + it.id + '\')">Verwijder</button></div></div>';
  }).join('');
}
function viewScriptLibraryItem(id) {
  const it = (state.scriptLibrary || []).find(function(x){ return x.id === id; });
  if (!it) return;
  state.lastScript = it.script;
  state.lastScriptContext = { type: it.type, source: it.source || null, meta: it.meta || {} };
  const el = document.getElementById('scriptlib-list');
  if (!el) return;
  let h = '<button class="btn btn-small btn-ghost" onclick="renderScriptLibrary()" style="margin-bottom:16px;">&larr; Terug naar overzicht</button>';
  if (it.source) {
    h += '<div class="slib-src"><h4>Bron, waaruit dit script is geitereerd</h4>';
    if (it.source.metrics) h += '<div class="slib-meta" style="margin:0;"><strong>Cijfers van de geteste video:</strong></div><pre>' + escapeHtml(it.source.metrics) + '</pre>';
    if (it.source.goal) h += '<div class="slib-meta" style="margin-top:10px;"><strong>Doel:</strong> ' + escapeHtml(it.source.goal) + '</div>';
    if (it.source.source_script_text) h += '<div class="slib-meta" style="margin-top:10px;"><strong>Bronscript:</strong></div><pre>' + escapeHtml(it.source.source_script_text) + '</pre>';
    h += '</div>';
  }
  h += (typeof buildSwScriptHtml === 'function') ? buildSwScriptHtml(it.script || {}) : '';
  el.innerHTML = h;
  window.scrollTo({ top: 0, behavior: 'smooth' });
}
function deleteScriptLibraryItem(id) {
  if (!confirm('Dit bewaarde script verwijderen?')) return;
  state.scriptLibrary = (state.scriptLibrary || []).filter(function(x){ return x.id !== id; });
  saveScriptLibrary();
  renderScriptLibrary();
  toast('Script verwijderd');
}

